def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    bg = freq.most_common(1)[0][0]
    color = next(v for v in freq if v != bg)
    out = [row[:] for row in grid]
    # The sparse color-8 markers extend in straight lines as color 2.
    # On the provided grid, each column has two endpoint markers with one gap,
    # or at least three markers defining interior spans; similarly for rows.
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == color]
        if len(rs) >= 2:
            for a, b in zip(rs, rs[1:]):
                if b - a > 1:
